-- ============================================================================
-- seeds/warcastle-tables-1-5.sql
--
-- The real set-ups for WarCastle tables 1 to 5 (Grant's sketches, 4 Nov),
-- laid out by hand in the scenario builder's format, with no deployment (the
-- attack sets that) and no objective markers:
--   1 Talabec River: a winding river, a stone bridge in the centre, four woods.
--   2 Fortenhaf Ferry: a river with a wooden footbridge on the right, two
--     swamps and two ferry buildings on the south bank.
--   3 Gryphon Woods: four swamps, two burnt woods, the Hanging Tree (special
--     feature) in the centre.
--   4 Nagenhof Woods: six woods and the World Roots (special feature).
--   5 Peak Pass: a road through the middle, three hills either side.
-- Terrain can still be moved in Set up > Tables.
--
-- Run in the Supabase SQL editor, after seeds/warcastle.sql (and after
-- seeds/warcastle-tables.sql, if that's run again: it puts the dummies back).
-- It sets tables 1 to 5 and leaves 6 to 13 as they are. Then re-run
-- seeds/warcastle-test.sql to copy them into WarCastle (test).
-- Safe to run again: the scenarios keep their ids.
-- ============================================================================

do $do$
declare
  v_campaign campaigns%rowtype;
  v_tables   jsonb := '{}'::jsonb;
  r          jsonb;
begin
  select * into v_campaign from campaigns where name = 'WarCastle' and settings ->> 'template' = 'warcastle';
  if not found then raise exception 'No WarCastle event found: run seeds/warcastle.sql first.'; end if;

